style.css:
@-moz-document domain("youtube.com") {
/* ===== SECTION 1: Image + ambient colored light + dark overlay ===== */
  html, body, ytd-app {
    background:
      radial-gradient(ellipse at 20% 100%, rgba(247,37,133,0.35), transparent 50%),
      radial-gradient(ellipse at 50% 100%, rgba(76,201,240,0.35), transparent 50%),
      radial-gradient(ellipse at 80% 100%, rgba(255,209,102,0.35), transparent 50%),
      linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)),
      url("https://i.ytimg.com/vi/Bl7AG1DpSDQ/mqdefault.jpg") center/cover no-repeat fixed !important;
  }

  /* ===== SECTION 2: See-through page layers ===== */
  html, html[dark] {
    --yt-spec-base-background: transparent !important;
    --yt-spec-general-background-a: transparent !important;
    --yt-spec-general-background-b: transparent !important;
  }
  ytd-browse, ytd-watch-flexy, ytd-search, #page-manager {
    background: transparent !important;
  }

  /* ===== SECTION 3: Readable text ===== */
  #video-title, ytd-channel-name, #metadata-line, yt-formatted-string {
    text-shadow: 0 1px 4px rgba(0,0,0,0.9);
  }

  /* ===== SECTION 4: Animations ===== */
  @keyframes note-a {
    0%   { transform: translate(0, 0) rotate(-15deg) scale(0.5); opacity: 0; }
    10%  { opacity: 1; }
    30%  { transform: translate(50px, -30vh) rotate(15deg) scale(1); }
    60%  { transform: translate(-50px, -65vh) rotate(-15deg) scale(1.15); }
    100% { transform: translate(30px, -125vh) rotate(20deg) scale(0.8); opacity: 0; }
  }
  @keyframes note-b {
    0%   { transform: translate(0, 0) rotate(15deg) scale(0.5); opacity: 0; }
    10%  { opacity: 1; }
    30%  { transform: translate(-60px, -30vh) rotate(-20deg) scale(1.1); }
    60%  { transform: translate(60px, -65vh) rotate(20deg) scale(1); }
    100% { transform: translate(-30px, -125vh) rotate(-15deg) scale(0.7); opacity: 0; }
  }
  @keyframes note-glow {
    0%, 100% { text-shadow: 0 0 8px var(--c), 0 0 18px var(--c), 0 0 36px var(--c); }
    50%      { text-shadow: 0 0 14px var(--c), 0 0 34px var(--c), 0 0 70px var(--c), 0 0 110px var(--c); }
  }

  /* ===== SECTION 5: Shared note style ===== */
  html::before, html::after,
  body::before, body::after,
  ytd-app::before, ytd-app::after,
  ytd-page-manager::before, ytd-page-manager::after,
  #content::before, #content::after {
    position: fixed;
    bottom: -90px;
    pointer-events: none;
    z-index: 2147483647;
    color: var(--c);
    animation-timing-function: ease-in-out;
    animation-iteration-count: infinite;
  }

  /* ===== SECTION 6: The 10 glowing notes (--c is each note's light color) ===== */
  html::before { content: "♪"; --c: #ffffff; left: 4%;  font-size: 50px; animation-name: note-a, note-glow; animation-duration: 9s, 2.5s;  animation-delay: 0s, 0s; }
  html::after  { content: "♫"; --c: #ffd166; left: 14%; font-size: 64px; animation-name: note-b, note-glow; animation-duration: 12s, 3s;  animation-delay: 2s, 0s; }
  body::before { content: "♩"; --c: #ef476f; left: 24%; font-size: 54px; animation-name: note-a, note-glow; animation-duration: 8s, 2s;   animation-delay: 4s, 0s; }
  body::after  { content: "♬"; --c: #06d6a0; left: 34%; font-size: 70px; animation-name: note-b, note-glow; animation-duration: 13s, 3.5s; animation-delay: 1s, 0s; }
  ytd-app::before { content: "♪"; --c: #4cc9f0; left: 44%; font-size: 58px; animation-name: note-a, note-glow; animation-duration: 10s, 2.8s; animation-delay: 3s, 0s; }
  ytd-app::after  { content: "♫"; --c: #ffffff; left: 54%; font-size: 48px; animation-name: note-b, note-glow; animation-duration: 7s, 2.2s;  animation-delay: 5s, 0s; }
  ytd-page-manager::before { content: "♬"; --c: #f72585; left: 64%; font-size: 66px; animation-name: note-a, note-glow; animation-duration: 11s, 3s;  animation-delay: 0.5s, 0s; }
  ytd-page-manager::after  { content: "♩"; --c: #ffd166; left: 74%; font-size: 52px; animation-name: note-b, note-glow; animation-duration: 9s, 2.6s;  animation-delay: 6s, 0s; }
  #content::before { content: "♪"; --c: #06d6a0; left: 84%; font-size: 60px; animation-name: note-a, note-glow; animation-duration: 8s, 2.4s;  animation-delay: 2.5s, 0s; }
  #content::after  { content: "♫"; --c: #ffffff; left: 94%; font-size: 46px; animation-name: note-b, note-glow; animation-duration: 10s, 3.2s; animation-delay: 7s, 0s; }
}
